package com.yuegang.zhihui.search.application;import com.yuegang.zhihui.common.core.*;import java.util.Map;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.client.RestClient;public final class SearchDeletionService{private final JdbcTemplate jdbc;private final RestClient elastic;private final String alias;public SearchDeletionService(JdbcTemplate j,String base,String a){jdbc=j;elastic=RestClient.builder().baseUrl(base).build();alias=a;}public void deleteDocument(String document){long id;try{id=Long.parseLong(document);if(id<=0)throw new NumberFormatException();}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}jdbc.update("DELETE FROM search_embedding WHERE document_id=?",id);elastic.post().uri("/"+alias+"/_delete_by_query?conflicts=proceed&refresh=true").body(Map.of("query",Map.of("term",Map.of("documentId",document)))).retrieve().toBodilessEntity();}}
